exercise.solution:
def rejeu_client(cache, cle, tache):
    if cle not in cache:return None
    ancienne,resultat=cache[cle]
    if ancienne!=tache:raise ValueError('clé contradictoire')
    return resultat

exercise.check:
cache={'a':('tâche 1',{'status':'finished'})}
assert rejeu_client(cache,'a','tâche 1')=={'status':'finished'}
assert rejeu_client(cache,'b','tâche 2') is None
try:rejeu_client(cache,'a','autre tâche')
except ValueError:pass
else:raise AssertionError('rejeu contradictoire')
